/* EventAuditingOptions is sized by the MaximumAuditEventCount after it */
static int
lsa_LSAPR_POLICY_AUDIT_EVENTS_INFO_EventAuditingOptions_deferred_coder(char *name, struct dcerpc_context *dce,
                struct dcerpc_pdu *pdu,
                struct dcerpc_iovec *iov,
                void *ptr)
{
        struct lsa_LSAPR_POLICY_AUDIT_EVENTS_INFO *s = ptr;

        dcerpc_set_size_is(pdu, s->MaximumAuditEventCount);
        if (dcerpc_pdu_direction(pdu) == DCERPC_DECODE && s->MaximumAuditEventCount) {
                if (s->EventAuditingOptions == NULL) {
                        s->EventAuditingOptions = dcerpc_alloc_array(pdu, iov,
                                s->MaximumAuditEventCount, sizeof(uint32_t));
                        if (s->EventAuditingOptions == NULL) {
                                return -1;
                        }
                }
        }
        return lsa_uint32_t_carray_coder(name, dce, pdu, iov,
                s->EventAuditingOptions ? (void *)s->EventAuditingOptions : (void *)&s->EventAuditingOptions);
}

int
lsa_LSAPR_POLICY_AUDIT_EVENTS_INFO_coder(char *name, struct dcerpc_context *dce,
                struct dcerpc_pdu *pdu,
                struct dcerpc_iovec *iov,
                void *ptr)
{
        struct lsa_LSAPR_POLICY_AUDIT_EVENTS_INFO *s = ptr;

        (void)name;
        if (dcerpc_uint8_coder("AuditingMode", dce, pdu, iov, &s->AuditingMode)) {
                return -1;
        }
        if (dcerpc_pdu_encoding(pdu) != ENCODING_NDR) {
                if (dcerpc_uint32_coder("MaximumAuditEventCount", dce, pdu, iov, &s->MaximumAuditEventCount)) {
                        return -1;
                }
                if (dcerpc_pdu_direction(pdu) == DCERPC_DECODE &&
                    (s->MaximumAuditEventCount > 1000)) {
                        return -1;
                }
                dcerpc_set_size_is(pdu, s->MaximumAuditEventCount);
                if (dcerpc_pdu_direction(pdu) == DCERPC_DECODE && s->MaximumAuditEventCount) {
                        if (s->EventAuditingOptions == NULL) {
                                s->EventAuditingOptions = dcerpc_alloc_array(pdu, iov,
                                        s->MaximumAuditEventCount, sizeof(uint32_t));
                                if (s->EventAuditingOptions == NULL) {
                                        return -1;
                                }
                        }
                }
                if (dcerpc_ptr_coder("EventAuditingOptions", dce, pdu, iov,
                                     (dcerpc_pdu_direction(pdu) == DCERPC_DECODE &&
                                      s->EventAuditingOptions == NULL) ? (void *)&s->EventAuditingOptions : (void *)s->EventAuditingOptions,
                                     PTR_UNIQUE, lsa_uint32_t_carray_coder)) {
                        return -1;
                }
        } else if (dcerpc_ptr_coder("EventAuditingOptions", dce, pdu, iov,
                         (dcerpc_pdu_direction(pdu) == DCERPC_ENCODE &&
                          s->EventAuditingOptions == NULL) ? NULL : (void *)s,
                         PTR_UNIQUE, lsa_LSAPR_POLICY_AUDIT_EVENTS_INFO_EventAuditingOptions_deferred_coder)) {
                return -1;
        }
        if (dcerpc_pdu_encoding(pdu) == ENCODING_NDR) {
                if (dcerpc_uint32_coder("MaximumAuditEventCount", dce, pdu, iov, &s->MaximumAuditEventCount)) {
                        return -1;
                }
                if (dcerpc_pdu_direction(pdu) == DCERPC_DECODE &&
                    (s->MaximumAuditEventCount > 1000)) {
                        return -1;
                }
        }

        return 0;
}

